param(
    [string]$QtDir = $env:QTDIR,
    [string]$MinGw = $env:MINGW,
    [switch]$Clean
)

$ErrorActionPreference = 'Stop'

if (-not $QtDir) { $QtDir = 'C:\Qt\Qt5.12.12\5.12.12\mingw73_64' }
if (-not $MinGw) { $MinGw = 'C:\Qt\Qt5.12.12\Tools\mingw730_64' }

$qmake = Join-Path $QtDir 'bin\qmake.exe'
$make = Join-Path $MinGw 'bin\mingw32-make.exe'
$windeployqt = Join-Path $QtDir 'bin\windeployqt.exe'

if (-not (Test-Path $qmake)) { Write-Error "qmake not found: $qmake. Set -QtDir or QTDIR." }
if (-not (Test-Path $make)) { Write-Error "mingw32-make not found: $make. Set -MinGw or MINGW." }
if (-not (Test-Path $windeployqt)) { Write-Error "windeployqt not found: $windeployqt. Set -QtDir or QTDIR." }

$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $scriptDir

$env:PATH = "$($QtDir)\bin;$($MinGw)\bin;$env:PATH"

try {
    if ($Clean) {
        Write-Host '[STEP] clean'
        & $make clean | Write-Host
    }

    Write-Host '[STEP] qmake (release)'
    & $qmake 'PyrobTaskBuilder.pro' '-spec' 'win32-g++' 'CONFIG+=release' | Write-Host

    Write-Host '[STEP] mingw32-make'
    & $make '-j4'

    Write-Host '[STEP] windeployqt'
    & $windeployqt 'bin\PyrobTaskBuilder.exe' '--release' '--compiler-runtime' | Write-Host

    $exe = (Resolve-Path 'bin\PyrobTaskBuilder.exe').Path
    Write-Host "[OK] Build complete: $exe"
} catch {
    Write-Error $_
    exit 1
}

# Usage examples:
#   powershell -ExecutionPolicy Bypass -File .\build_mingw64.ps1
#   powershell -ExecutionPolicy Bypass -File .\build_mingw64.ps1 -QtDir 'C:\Qt\Qt5.12.12\5.12.12\mingw73_64' -MinGw 'C:\Qt\Qt5.12.12\Tools\mingw730_64' -Clean





